// ============================================================
// 后台列表与匿名化
// ============================================================
// ⚠️ sqlc 不做动态查询（ADR 0006 §15.4）。后台的多条件任意组合筛选
//
//	要么退化成手写 pgx，要么用这种「NULL = 不过滤」的固定形状。这里选后者。
func (q *Queries) ListUsersForAdmin(ctx context.Context, arg ListUsersForAdminParams) ([]ListUsersForAdminRow, error) {
	rows, err := q.db.Query(ctx, listUsersForAdmin,
		arg.Limit,
		arg.Offset,
		arg.PlanID,
		arg.Banned,
		arg.EmailLike,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListUsersForAdminRow{}
	for rows.Next() {
		var i ListUsersForAdminRow
		if err := rows.Scan(
			&i.ID,
			&i.Email,
			&i.PlanID,
			&i.GroupID,
			&i.TransferEnable,
			&i.ExpiredAt,
			&i.Banned,
			&i.CreatedAt,
			&i.LastLoginAt,
			&i.U,
			&i.D,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const markEmailProbeRedeemed = `-- name: MarkEmailProbeRedeemed :exec
UPDATE email_log SET redeemed_at = now()
WHERE id = (
  SELECT el.id FROM email_log el
  WHERE lower(el.to_email) = lower($1) AND el.template = $2 AND el.redeemed_at IS NULL
  ORDER BY el.created_at DESC
  LIMIT 1
)
`

type MarkEmailProbeRedeemedParams struct {
	Lower    string `json:"lower"`
	Template string `json:"template"`
}

// 用户回填验证码的时刻。sent_at → redeemed_at 的差值就是**真实端到端送达时延**，
// 这是 ADR 0002 §7 要求的送达率实测数据里唯一无法从 ESP 回调拿到的一项。
// ⚠️ 子查询必须起别名：不起别名时 `template` 同时可解析到外层 UPDATE 的目标表，
//
//	PG 直接报 "column reference is ambiguous"。
func (q *Queries) MarkEmailProbeRedeemed(ctx context.Context, arg MarkEmailProbeRedeemedParams) error {
	_, err := q.db.Exec(ctx, markEmailProbeRedeemed, arg.Lower, arg.Template)
	return err
}

